// ===== CONFIGURACIÓN (edita aquí) =====
const VENDEDORES = [
  // id = ID del usuario en el sistema (Admin > Usuarios), email = a donde llega el aviso
  { id: 1, nombre: 'Vendedor 1', email: 'vendedor1@equiterm.com' },
  { id: 2, nombre: 'Vendedor 2', email: 'vendedor2@equiterm.com' },
];
const BUZONES_QUE_CUENTAN = []; // ej: ['ventas@equitermindustries.com.mx']  ([] = cualquier buzón del dominio)
const IGNORAR_REMITENTES = /(no-?reply|noreply|mailer-daemon|postmaster|notifications?@|@equiterm\.)/i;
const IGNORAR_RESPUESTAS = false; // true = ignora correos que son respuesta a otro (In-Reply-To)
const SOLO_SI_ASUNTO_O_TEXTO_CONTIENE = null; // ej: /cotiz|precio|caldera|presupuesto/i  (null = todos)
// ======================================

// Hostinger envía { id, event, timestamp, data: {...} } (n8n lo entrega dentro de body)
const j = $json.body ?? $json;
const d = j.data ?? {};

// "Nombre <correo@dominio>" -> nombre + correo
const fromRaw = (d.from || '').toString().trim();
const m = fromRaw.match(/^(.*?)\s*<([^>]+)>\s*$/);
const email = (m ? m[2] : fromRaw).trim().toLowerCase();
const name = (m ? m[1] : '').replace(/^["']|["']$/g, '').trim();

const subject = (d.subject || '').toString().trim();
const body = (d.plainBody || '').toString().replace(/\s+\n/g, '\n').trim();
const messageId = (d.messageId || d.eventId || j.id || (email + '|' + subject + '|' + (d.date || ''))).toString();
const mailbox = (d.mailboxAddress || '').toLowerCase();

const autoReply = /auto(matic)?[- ]?(reply|respuesta)|out of office|fuera de la oficina/i.test(subject);
let valido = j.event === 'message.received' && !!email && !IGNORAR_REMITENTES.test(email) && !autoReply;
if (valido && BUZONES_QUE_CUENTAN.length) valido = BUZONES_QUE_CUENTAN.includes(mailbox);
if (valido && IGNORAR_RESPUESTAS && d.inReplyTo) valido = false;
if (valido && SOLO_SI_ASUNTO_O_TEXTO_CONTIENE) valido = SOLO_SI_ASUNTO_O_TEXTO_CONTIENE.test(subject + ' ' + body);

// Reparto equitativo (round robin) entre vendedores
const sd = $getWorkflowStaticData('global');
let vendedor = null;
if (valido && VENDEDORES.length) {
  sd.rr = ((sd.rr ?? -1) + 1) % VENDEDORES.length;
  vendedor = VENDEDORES[sd.rr];
}

return {
  json: {
    valido,
    vendedor,
    payload: {
      message_id: messageId,
      email,
      name: name || null,
      subject,
      message: body,
      received_at: d.date ? new Date(d.date).toISOString() : new Date().toISOString(),
      assigned_to: vendedor ? vendedor.id : null,
      create_task: true,
    },
  },
};
